import{_ as c,r as e,o as l,c as i,e as t,a as s,d as n,s as r}from"./chunks/framework.CXcwiNg-.js";const m=JSON.parse('{"title":"Сессия - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Конфигурация","slug":"конфигурация","link":"#конфигурация","children":[]},{"level":2,"title":"Сохранение данных","slug":"сохранение-данных","link":"#сохранение-данных","children":[]},{"level":2,"title":"Получение данных","slug":"получение-данных","link":"#получение-данных","children":[]},{"level":2,"title":"Удаление данных","slug":"удаление-данных","link":"#удаление-данных","children":[]},{"level":2,"title":"Регенерация сессии","slug":"регенерация-сессии","link":"#регенерация-сессии","children":[]},{"level":2,"title":"Временные данные","slug":"временные-данные","link":"#временные-данные","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/extend/services/session.md","filePath":"3.x/ru/extend/services/session.md"}'),u={name:"3.x/ru/extend/services/session.md"};function d(k,a,g,h,v,f){const o=e("pre-heading"),p=e("post-heading");return l(),i("div",null,[t(o),a[0]||(a[0]=s("h1",null,"Сессия",-1)),t(p),a[1]||(a[1]=s("p",null,[n("Поскольку HTTP-приложения не имеют состояния, сессии предоставляют способ хранения информации о пользователе между запросами. October CMS поставляется с разнообразными интерфейсами сессий, доступными для использования через единый API. Поддержка популярных сервисов, таких как "),s("a",{href:"http://memcached.org",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Memcached"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n(", "),s("a",{href:"https://redis.io",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("Redis"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])]),n(" и базы данных, включена из коробки.")],-1)),a[2]||(a[2]=r(`<h2 id="конфигурация"><a href="#конфигурация" class="header-anchor">#</a> Конфигурация</h2><p>Конфигурация сессии хранится в <code>config/session.php</code>. Обязательно ознакомьтесь с документированными опциями, доступными вам в этом файле.</p><ul><li><code>file</code> — сессии хранятся в <code>storage/framework/sessions</code>.</li><li><code>cookie</code> — сессии хранятся в безопасных, зашифрованных cookies.</li><li><code>database</code> — сессии хранятся в базе данных, используемой вашим приложением.</li><li><code>memcached</code> / <code>redis</code> — сессии хранятся в одном из этих быстрых хранилищ на основе кэша.</li><li><code>array</code> — сессии хранятся в простом PHP-массиве и не будут сохраняться между запросами.</li></ul><p>По умолчанию October CMS настроен на использование драйвера сессий <code>file</code>, который хорошо подходит для большинства приложений. Драйвер <code>array</code> обычно используется для запуска модульных тестов для предотвращения сохранения данных сессии.</p><h2 id="сохранение-данных"><a href="#сохранение-данных" class="header-anchor">#</a> Сохранение данных</h2><p>Используя фасад <code>Session</code>, вы можете вызывать различные функции для взаимодействия с базовыми данными. Например, метод <code>put</code> сохраняет новый фрагмент данных в сессии.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>October CMS использует ключ сессии <code>flash</code> внутренне, поэтому вы должны избегать использования этого имени в качестве ключа.</p></div><p>Метод <code>push</code> может использоваться для добавления нового значения к значению сессии, которое является массивом. Например, если ключ <code>user.teams</code> содержит массив названий команд, вы можете добавить новое значение в массив следующим образом:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;user.teams&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;developers&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="получение-данных"><a href="#получение-данных" class="header-anchor">#</a> Получение данных</h2><p>Когда вы получаете значение из сессии, вы также можете передать значение по умолчанию в качестве второго аргумента метода <code>get</code>. Это значение по умолчанию будет возвращено, если указанный ключ не существует в сессии. Если вы передаёте <code>Closure</code> в качестве значения по умолчанию в метод <code>get</code>, <code>Closure</code> будет выполнено и его результат возвращён.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;default&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;key&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;default&#39;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вы хотите получить все данные из сессии, вы можете использовать метод <code>all</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$data</span> <span class="token operator">=</span> <span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>has</code> может использоваться для проверки, существует ли элемент в сессии. Этот метод вернёт <code>true</code>, если элемент существует.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">has</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;users&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="удаление-данных"><a href="#удаление-данных" class="header-anchor">#</a> Удаление данных</h2><p>Метод <code>pull</code> извлечёт и удалит элемент из сессии.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$value</span> <span class="token operator">=</span> <span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">pull</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;default&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод <code>forget</code> удалит фрагмент данных из сессии. Если вы хотите удалить все данные из сессии, вы можете использовать метод <code>flush</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">forget</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">flush</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="регенерация-сессии"><a href="#регенерация-сессии" class="header-anchor">#</a> Регенерация сессии</h2><p>Если вам нужно регенерировать идентификатор сессии, вы можете использовать метод <code>regenerate</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">regenerate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Чтобы регенерировать идентификатор сессии и удалить все данные из сессии в одном выражении, вы можете использовать метод <code>invalidate</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">invalidate</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="временные-данные"><a href="#временные-данные" class="header-anchor">#</a> Временные данные</h2><p>Иногда вы можете захотеть сохранить элементы в сессии только для следующего запроса. Вы можете сделать это с помощью метода <code>Session::flash</code>. Данные, сохранённые в сессии с помощью этого метода, будут доступны только во время следующего HTTP-запроса, а затем будут удалены. Временные данные в основном полезны для кратковременных сообщений о состоянии.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">flash</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вам нужно сохранить временные данные на более длительный период, вы можете использовать метод <code>reflash</code>, который сохранит все временные данные на дополнительный запрос. Если вам нужно сохранить только определённые временные данные, вы можете использовать метод <code>keep</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">reflash</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Session</span><span class="token operator">::</span><span class="token function">keep</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;username&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4>`,33)),a[3]||(a[3]=s("div",{class:"custom-block also"},[s("ul",null,[s("li",null,[s("a",{href:"https://laravel.com/docs/10.x/session",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("HTTP-сессия Laravel"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),s("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const w=c(u,[["render",d]]);export{m as __pageData,w as default};
